def _bridge_guard(real):
    """pywebview's js_bridge_call, allowed ONE call (6b321): api_token()
    with no arguments and a plain reply id. pywebview resolves the name
    one getattr at a time, dunders included, so a page (on macOS any
    frame, the map's third-party iframe too) that posted
    'api_token.__func__.__globals__.get' would read or write this
    module's globals, the key and token among them; and it pastes the
    reply id into a script unescaped. Everything else is dropped.
    A build with accounts (M9) allows three more, each only on the object
    that has it: the main window's open_account(task) with one task of
    the allow-list, and the account window's account_token() and
    account_close() with none, answered without pywebview's eval (the
    account page's CSP refuses eval; _bridge_reply)."""
    def js_bridge_call(window, func_name, param, value_id):
        if not re.fullmatch(r"[0-9A-Za-z_.+-]{0,40}", str(value_id)):
            return None
        if func_name == "api_token" and param in (None, []):
            return real(window, func_name, [], value_id)
        g = globals()
        if g.get("ACCOUNTS") is not True:
            return None
        api = getattr(window, "_js_api", None)
        if (func_name == "open_account" and isinstance(param, list)
                and len(param) == 1 and param[0] in g["ACCOUNT_TASKS"]
                and isinstance(api, g["_WindowBridgeAcct"])):
            return real(window, func_name, [param[0]], value_id)
        if (func_name in ("account_token", "account_close")
                and param in (None, []) and isinstance(api, g["_AccountBridge"])):
            return g["_bridge_reply"](window, func_name, value_id)
        return None
    js_bridge_call._guarded = True
    return js_bridge_call


_BRIDGE_OK = False
if HAS_WEBVIEW:
    # before any backend module is imported: each binds the name at import
    # (from webview.util import js_bridge_call), so patch those too
    try:
        import webview.util as _wu
        if not getattr(_wu.js_bridge_call, "_guarded", False):
            _wu.js_bridge_call = _bridge_guard(_wu.js_bridge_call)
        for _mn, _mm in list(sys.modules.items()):
            if (_mn.startswith("webview.platforms.") and _mm is not None
                    and hasattr(_mm, "js_bridge_call")):
                _mm.js_bridge_call = _wu.js_bridge_call
        _BRIDGE_OK = True
    except Exception:
        # no guard, no bridge: the window opens without js_api and the
        # page says it can't start, rather than run with the bridge open
        pass

APP_VERSION = "7.0.0"   # bump here — UI, window, DMG all follow
# BETA HOLD (per Patrick): the 6.x line is beta until the kinks are out.
# While > 0: every display surface says "beta N", release.sh publishes
# as a GitHub PRERELEASE, and — because the desktop updater reads
# /releases/latest, which EXCLUDES prereleases — every stable install
# stays parked on the last stable.
# NUMBERED PER LINE (6b286, per Patrick, the macOS way): "6.1 beta 1",
# "6.1 beta 2"… four or five a line, restarting at 1 with each new
# version — never the build number ("beta 268"). 0 = not a beta.
# `./release.sh beta` cuts the next one; a stable cut resets it to 0.
APP_BETA = 0
# RELEASE CANDIDATE (6b258, per Patrick: "almost there"). >0 renames
# the label from "beta" to "RC<n>" on every display surface and in the
# release title, while KEEPING the prerelease hold above — an RC is
# still not the stable build, so /releases/latest must not offer it.
# Set back to 0 when 6.1 ships for real (after sign-on + cloud sync).
APP_RC = 0
# CHANNELS (6b285, per Patrick): stable, beta, nightly. A nightly is the
# single rolling `nightly` release GitHub Actions rebuilds on every push
# to main; CI stamps this constant with "<run> <sha7>" so the app knows
# which commit it is and the updater can tell a newer nightly by SHA.
APP_NIGHTLY = ""
# THE BRAND (6b257): ConcordeAI — Concorde grew its AI, and the AI is
# BOLD in every lockup (nested <b>, see .vghost). Every user-facing
# surface says ConcordeAI; everything load-bearing stays "MillenAI" —
# app_dir, bundle id, the executable name (_SWAP_SCRIPT pgreps it),
# User-Agents — so data, permissions and the self-update chain survive
# both renames.
APP_NAME = "ConcordeAI"


def brand(html: str) -> str:
    """User-facing copy carries the brand; code and paths keep MillenAI."""
    return html.replace("MillenAI", APP_NAME)


def short_version(v: str = None) -> str:
    """Display form: ONE trailing .0 falls away, never more (6b242, per
    Patrick) — '6.0.0'->'6.0', '6.1.0'->'6.1', '6.1.1' and '6.0.1' stay
    as they are. The old loop kept going and turned 6.0.0 into a bare
    '6', which reads like a major line rather than a version.

    Display-ONLY — the beta/RC suffix rides along here. Anything that
    compares or builds artifacts uses APP_VERSION raw."""
    v = v or APP_VERSION
    if v.count(".") >= 2 and v.endswith(".0"):
        v = v[:-2]
    if APP_NIGHTLY:
        return v + " nightly " + APP_NIGHTLY.split()[-1]
    if APP_RC:
        # NO build number here (per Patrick): an RC is named, not
        # numbered — "6.1 RC1", full stop. The updater still compares
        # the TAG's build, so a newer RC1 cut is offered correctly even
        # though both read the same on screen.
        return v + " RC%d" % APP_RC
    return v + (" beta %d" % APP_BETA if APP_BETA else "")


def spec_version() -> str:
    """The rail's spec cell is a few mono characters short of a nightly's
    full name (6b289, per Patrick: "VERSION 6.0.4 NIGHTLY E6F…" —
    "consolidate that version number so there's no ellipsis"). There the
    commit alone says nightly — no other build carries one — so the
    word goes: "6.0.4 · e6fb576". Betas and RCs already fit."""
    return short_version().replace(" nightly ", " \u00b7 ")
