def resolve_agent(name):
    """(model_label, agent_dict) — best installed pick, or (None, None)."""
    a = AGENTS.get(name)
    if not a:
        return None, None
    pulled = ollama_pulled_tags() or set()
    for l in a["picks"]:
        if l in MODEL_ROUTES and model_cached(l, pulled) \
                and model_fits_memory(l):
            return l, a
    return None, a


# AGENTS UI IS PULLED (6 beta 209, per Patrick: "until i get the
# logistics of that sorted") — the AGENTS dict, AGENT_META and the
# Code tab's two specialists stay live; the Agents TAB and the
# specialist list are gone from the page until this flips back.
SHOW_AGENTS = False

# The CODE tab owns the two code specialists (5.2, per Patrick: "pull
# coding from agents and make it into a 3rd tab"); Agents keeps the rest.
CODE_AGENTS = ("Coding", "Workspace", "Remote")
# THE CLOUD ROLE EACH LANE ANSWERS IN (6b308, per Patrick: "selecting the
# ideal model for different tasks"). Research and Remote run their own
# flows; anything not listed is the quick answer.
LANE_ROLE = {"Coding": "code", "Workspace": "code", "Math & Logic": "work",
             "Writing": "work", "Resumes": "work",
             "Hermes": "fast", "Mnemosyne": "fast"}


def build_agent_rows() -> str:
    out = ['  <div class="agent" data-agent="">'
           '<span class="radio"></span><span class="ico">🤖</span>'
           'Standard model</div>']
    for name, a in AGENTS.items():
        if name in CODE_AGENTS:
            continue
        out.append(
            f'  <div class="agent" data-agent="{name}" title="{a["desc"]}">'
            f'<span class="radio"></span><span class="ico">{a["icon"]}</span>'
            f'{name}</div>')
    return "\n".join(out)


def build_code_rows() -> str:
    out = []
    for name in CODE_AGENTS:
        a = AGENTS.get(name)
        if not a:
            continue
        out.append(
            f'  <div class="agent" data-agent="{name}" title="{a["desc"]}">'
            f'<span class="radio"></span><span class="ico">{a["icon"]}</span>'
            f'{name}</div>')
    return "\n".join(out)


# Auto-blending skips these: a vision model answers text poorly, and 1B-class
# models degrade into repetition (observed looping "address address address").
BLEND_EXCLUDE = {"Qwen 3.5 Vision 9B"}
BLEND_MIN_MEM = 2.4e9

THINK_HINT = ("Work through this carefully and step by step before giving "
              "your final answer.")


def resolve_tier(name: str) -> list:
    """Concrete model list for a tier, given what's actually usable now.

    The tier's own picks come first, then any other installed model that
    fits in RAM is blended in (strongest first) up to the tier's cap — so
    downloading more models makes Pro and Thinking richer automatically.
    """
    t = TIERS.get(name)
    if not t:
        return []
    return _tier_ready(name)[:t["count"]]


def _tier_ready(name: str) -> list:
    """What resolve_tier chooses from on THIS computer, strongest first and
    not yet cut to the tier's count."""
    t = TIERS.get(name)
    if not t:
        return []
    if t.get("cloud_only"):
        return []       # by definition: no local model may take part
    pulled = ollama_pulled_tags() or set()

    def usable(l):
        # a giant on Ollama is for hand-picked questions only (6b314)
        return (l in MODEL_ROUTES and model_cached(l, pulled)
                and model_fits_memory(l) and not slow_giant(l))

    take_all = t.get("all")

    def blendable(l):
        if take_all:
            # Pro: memory is the only QUALITY limit — but BLEND_EXCLUDE
            # still applies (6b245): it exists to keep the vision model
            # out of TEXT councils, and take_all was bypassing it, so
            # LLaVA spent an engine swap drafting on prose questions.
            # Images never come through here — they route to LLaVA
            # directly before the tier resolves.
            return usable(l) and l not in BLEND_EXCLUDE
        return (usable(l) and l not in BLEND_EXCLUDE
                and MODEL_MEM_BYTES.get(l, 0) >= BLEND_MIN_MEM)

    ready = [l for l in t["picks"] if usable(l)]
    if t["count"] > 1:
        # Only blend in models that leave room for the others. A 70B needs
        # most of the machine, so pairing it with four more would thrash
        # (and take many minutes) even if it fits on its own right now.
        total = psutil.virtual_memory().total if HAS_PSUTIL else 0
        # the 45% cap keeps one huge model from crowding a blend; Power
        # deliberately ignores it and relies on the real memory check
        budget = float("inf") if take_all else (
            total * 0.45 if total else float("inf"))
        ready += [l for l in MERGE_RANK
                  if blendable(l) and l not in ready
                  and MODEL_MEM_BYTES.get(l, 0) <= budget]
    if not ready:  # nothing at all from the tier — fall back to anything
        ready = [l for l in MERGE_RANK if usable(l)]
    return ready


# YOUR SERVER FIRST (6b339): Fast, Thinking and Pro seat the models of the
# person's own paired server BEFORE this computer's (Patrick: "it
# prioritizes those over the ones that are on their local device"; "if the
# server has any more suitable models, it should run those"). A seat is
# {label, fb, params}: `label` is the model, a server's ("<name> · <tag>")
# or a local one; `fb` is what answers in its place when the server
# doesn't, before its first word (this computer's copy of the same model,
# else the mode's own best local one, else nothing). The server's best
# suitable models (srv_role_ok, placement "gpu", fitting a card whose size
# the gateway reported, the per-server switch on, answering) fill the seats,
# strongest first; what the server can't fill is taken by this computer's
# own picks in their normal order, skipping a model the server already
# seated (the same tag). The count stays: Fast one, Thinking three, Pro all.
# The agents of the Code lane keep their own rule (a server's coder, else the
# server's copy of their first pick).
_TIER_ROLE = {"Fast": "fast", "Thinking": "think", "Pro": "all"}
# the most server models a mode seats (6b339, final review): Pro seats every
# model that fits, and a server holding a dozen drafts one after another
# (one card) past the 240 s the council's loop gets, so only the first
# four drafts landed. The rest fall to this computer's normal picks or are
# left out, and the tier's bubble says so
SRV_SEATS_MAX = 4
# the agents that may: the Code lane's prefer a coder; Research and Remote
# run their own flows on this computer and keep them
_AGENT_ROLE = {"Coding": "code", "Workspace": "code", "Math & Logic": "think",
               "Writing": "all", "Resumes": "all", "Hermes": "fast",
               "Mnemosyne": "fast"}


def _label_params(label: str):
    """Billions of parameters a catalog row says it has ("26B"), or None."""
    m = re.match(r"(\d+(?:\.\d+)?)B", str((MODEL_INFO.get(label) or {}).get("size") or ""), re.I)
    return float(m.group(1)) if m else None


def resolve_tier_seats(name: str, ctx=None) -> list:
    """resolve_tier, with ctx's own servers seated first (see above)."""
    t = TIERS.get(name)
    if not t or t.get("cloud_only"):
        return []
    ready, count = _tier_ready(name), t["count"]
    role = _TIER_ROLE.get(name)
    cands = []
    if role and ctx is not None:
        try:
            cands = [m for m in server_mode_candidates(ctx) if srv_role_ok(m["name"], role)]
        except Exception:
            cands = []
    if not cands:
        return [{"label": l, "fb": "", "params": _label_params(l)} for l in ready[:count]]
    speeds = server_speeds(ctx)
    # SERVER FIRST (Patrick: "it prioritizes those over the ones that are on
    # their local device"): the server's best suitable models fill the seats,
    # strongest first (quality and size, measured speed as the tiebreak);
    # what the server can't fill is taken by this computer's own picks in
    # their normal order, skipping a model the server already seated (the
    # same tag). The per-server switch is the way back to local-first.
    seats = []
    for m in srv_rank(cands, role, "normal", speeds):
        if len(seats) >= min(count, SRV_SEATS_MAX):
            break
        seats.append({"label": m["label"], "fb": "", "params": m.get("params"),
                      "tag": _srv_tag_key(m["name"])})
    taken = {st["tag"] for st in seats}
    for l in ready:
        if len(seats) >= count:
            break
        if _srv_tag_key((MODEL_INFO.get(l) or {}).get("ollama")) in taken:
            continue
        seats.append({"label": l, "fb": "", "params": _label_params(l)})
    # behind each server seat: this computer's copy of the same model when
    # it is installed, else the mode's own best local one
    local_tag = {_srv_tag_key((MODEL_INFO.get(l) or {}).get("ollama")): l for l in ready}
    first_local = next((st["label"] for st in seats if not server_label(st["label"])),
                       ready[0] if ready else "")
    for st in seats:
        if server_label(st["label"]):
            st["fb"] = local_tag.get(st.pop("tag", ""), "") or first_local
    return seats


def tier_server_cap(name: str, ctx=None):
    """(seated, of): when a mode's server models outnumber the seats the cap
    gives them (6b339, final review), how many sit and how many there are; else
    None. The tier's bubble says it."""
    t = TIERS.get(name)
    role = _TIER_ROLE.get(name)
    if not t or t.get("cloud_only") or not role or ctx is None:
        return None
    try:
        cands = [m for m in server_mode_candidates(ctx) if srv_role_ok(m["name"], role)]
    except Exception:
        return None
    if t["count"] <= SRV_SEATS_MAX:       # the cap only binds where a mode seats more
        return None
    return (SRV_SEATS_MAX, len(cands)) if len(cands) > SRV_SEATS_MAX else None


def resolve_agent_seat(name, ctx=None):
    """(label, agent, fb): resolve_agent, with ctx's server first for the
    agents that may (above). A coding agent takes a server's coder before
    anything; any agent takes the server's copy of its first usable pick."""
    label, a = resolve_agent(name)
    role = _AGENT_ROLE.get(name)
    if not a or not role or ctx is None:
        return label, a, ""
    try:
        cands = [m for m in server_mode_candidates(ctx) if srv_role_ok(m["name"], role)]
    except Exception:
        cands = []
    if not cands:
        return label, a, ""
    speeds = server_speeds(ctx)
    if role == "code":
        top = srv_rank(cands, "code", "normal", speeds)[:1]
        if top and _srv_flags(top[0]["name"])["coder"]:
            return top[0]["label"], a, label or ""
    pulled = ollama_pulled_tags() or set()
    for l in a["picks"]:
        tag = (MODEL_INFO.get(l) or {}).get("ollama")
        srv = server_copy(tag, cands, speeds) if tag else None
        local_ok = (l in MODEL_ROUTES and model_cached(l, pulled) and model_fits_memory(l))
        if srv is not None:
            return srv["label"], a, l if local_ok else (label or "")
        if local_ok:
            break
    return label, a, ""


# THE THREE SETS (6b405, per Patrick: "one set of three, defined once,
# shown the same way everywhere"). Light, Recommended and Everything, each
# inside the next. They replace seven names in three vocabularies: the
# wizard's Basic/Pro/Max, the Your models window's Fast/Pro/Max (where
# "Fast" and "Pro" were also the chat modes, with other meanings) and
# Settings' Minimum/Recommended/Full/Max, whose Full and Max came out the
# same with No limits ticked and whose "every model this machine can run"
# was said while half of them were missing. Built by ROLE from the ladders
# the modes already use, so no machine is ever written in here:
#   Light        the quick pair (Llama 3.2 3B and 1B) and ONE everyday
#                model that also writes merges: the largest Gemma 4 of
#                catalog size EVERYDAY_MAX_GB or less, else the largest
#                model of that size that isn't the vision model; pictures
#                fetch the vision model on first use
#   Recommended  Light, plus one model for each job a mode reaches for
#                here: Fast's answer (the first of its picks that fits),
#                the merger (merge_pref_label's order), Thinking's seats
#                (its picks, to its count; models already in count), the
#                code ladder's first and the vision model
#   Everything   every supported model that fits; with No limits also the
#                ones bigger than memory, and with the second box the
#                giants this computer can hold (model_fits_machine decides)
# Light and Recommended are sized by memory whatever No limits says
# (fits_by_memory) and never hold a giant. One row per download (the
# MODEL_ROUTES key, 6b317). target None is this computer; a server is
# {"vram": bytes} (6b407): a model fits when its Ollama file fits the
# card whole, by _srv_fits's own rule, and its key is the tag.
MODEL_SETS = ("light", "recommended", "everything")
MODEL_SET_NAMES = {"light": "Light", "recommended": "Recommended",
                   "everything": "Everything"}
# the old plans' names, as the install route and saved settings may say them
MODEL_SET_ALIASES = {"basic": "light", "min": "light",
                     "pro": "recommended", "rec": "recommended",
                     "max": "everything", "full": "everything",
                     "all": "everything"}
QUICK_PAIR = ("Llama 3.2 3B", "Llama 3.2 1B")
# what a first run installs until the person picks another (per Patrick)
FIRST_RUN_SET = "light"
EVERYDAY_MAX_GB = 8.5          # the catalog's size (cat_gb), as on a Mac
# who writes the merge, best first: merge_pref_label reads it too
MERGE_PREFS = ("Gemma 4 26B", "Gemma 4 12B")
# the code lane's local planner, strongest first: remote_driver reads it too
CODE_LADDER = ("Qwen 3.8 27B", "Qwen 3.6 35B MoE", "GPT-OSS 20B",
               "Gemma 4 26B", "Qwen 3.5 9B", "Gemma 4 12B", "Llama 3.2 3B")
VISION_MODEL = "Qwen 3.5 Vision 9B"


def model_set_key(name) -> str:
    """"light", "recommended" or "everything" for a set's name or an old
    plan's, in any case; '' for anything else."""
    k = str(name or "").strip().lower()
    k = MODEL_SET_ALIASES.get(k, k)
    return k if k in MODEL_SETS else ""


def _set_tag_bytes(tag: str) -> int:
    """What an Ollama tag downloads: the registry's size, else the
    catalog's for the row that names it."""
    if tag in OLLAMA_BYTES:
        return OLLAMA_BYTES[tag]
    for i in MODEL_INFO.values():
        if i["ollama"] == tag:
            return int(i["cat_gb"] * 1e9)
    return 0


def model_sets(target=None) -> dict:
    """{"light": [...], "recommended": [...], "everything": [...],
    "over": [...]}: catalog labels, each set inside the next, one per
    download (see above). "over" is what Everything holds beyond this
    computer's memory (No limits, the giants); a server's is empty."""
    if target is None:
        def fits(l):
            return (bool(SUPPORTED.get(l)) and not model_is_giant(l)
                    and fits_by_memory(l))

        def key(l):
            return MODEL_ROUTES.get(l, (None, l))
        pool = [l for l in MODEL_INFO
                if SUPPORTED.get(l) and model_fits_machine(l)]
    else:
        vram = (target or {}).get("vram")

        def card(l):
            tag = (MODEL_INFO.get(l) or {}).get("ollama")
            return bool(tag) and _srv_fits(
                {"placement": "gpu", "size": _set_tag_bytes(tag)}, vram, True)

        def fits(l):
            return card(l) and not model_is_giant(l)

        def key(l):
            return _srv_tag_key(MODEL_INFO[l]["ollama"])
        pool = [l for l in MODEL_INFO if card(l)]
    out, keys = [], set()

    def add(l):
        if l and fits(l) and key(l) not in keys:
            keys.add(key(l))
            out.append(l)

    def first(ladder):
        return next((l for l in ladder if fits(l)), None)
    small = sorted((l for l in MODEL_INFO if fits(l)
                    and MODEL_INFO[l]["cat_gb"] <= EVERYDAY_MAX_GB),
                   key=lambda l: -MODEL_INFO[l]["cat_gb"])
    everyday = (next((l for l in small if l.startswith("Gemma 4")), None)
                or next((l for l in small if _family_of(l) != "vision"
                         and l not in QUICK_PAIR), None))
    for l in QUICK_PAIR + (everyday,):
        add(l)
    light = list(out)
    add(first(TIERS["Fast"]["picks"]))
    add(first(MERGE_PREFS))
    seats = 0
    for l in TIERS["Thinking"]["picks"]:
        if seats >= TIERS["Thinking"]["count"]:
            break
        if fits(l):
            add(l)              # a model already in counts as a seat
            seats += 1
    add(first(CODE_LADDER))
    add(VISION_MODEL)
    rec = list(out)
    for l in pool:
        if key(l) not in keys:
            keys.add(key(l))
            out.append(l)
    return {"light": light, "recommended": rec, "everything": list(out),
            "over": ([l for l in out if not fits_by_memory(l)]
                     if target is None else []),
            # the giants box's models: Everything holding one is red, not
            # yellow (per Patrick)
            "giants": ([l for l in out if model_is_giant(l)]
                       if target is None else [])}


def model_set_chosen() -> str:
    """The set the person picked last (model_set; an old plan's name reads
    as its set), or ''."""
    try:
        return model_set_key(machine_prefs().get("model_set"))
    except Exception:
        return ""


def model_set_choose(key: str):
    """Remember the person's set, so the status and the More-models card
    follow THEIR set (6b405)."""
    key = model_set_key(key)
    if key:
        machine_prefs_update(lambda p: p.__setitem__("model_set", key))


def first_set_labels() -> list:
    """The set a first run downloads and its window waits for: the one the
    person picked, Light until they pick (Patrick: the default is the small one;
    "pro", reads as Recommended)."""
    return list(model_sets()[model_set_chosen() or FIRST_RUN_SET])


def model_sets_status(pulled=None, sets=None) -> dict:
    """ONE STATUS FOR EVERY SCREEN (6b405). Per set: its models, how many,
    the GB of the whole set and of what is still missing (only that would
    download), "same" (the smaller set it equals here, or ''), and a state:
    "yours" (the set the person picked while all of it is here; until they
    pick, the largest set all here), "installed" (all here) or "download".
    "every" is True only while Everything is all here: nothing may say
    "every model this machine can run" otherwise. Compared by download,
    not by row (6b317)."""
    if pulled is None:
        pulled = ollama_pulled_tags() or set()
    sets = sets or model_sets()

    def dk(l):
        return MODEL_ROUTES.get(l, (None, l))
    have = {dk(l) for l, ok in SUPPORTED.items()
            if ok and model_cached(l, pulled)}
    chosen = model_set_chosen()
    out = {"chosen": chosen, "over": list(sets.get("over") or []),
           "risky": bool(sets.get("over")),
           "danger": bool(sets.get("giants"))}
    full = []
    for i, k in enumerate(MODEL_SETS):
        ls = list(sets[k])
        ks = {dk(l) for l in ls}
        miss = [l for l in ls if dk(l) not in have]
        same = next((p for p in MODEL_SETS[:i]
                     if ks and {dk(l) for l in sets[p]} == ks), "")
        out[k] = {"labels": ls, "n": len(ls), "missing": miss, "same": same,
                  "gb": round(sum(MODEL_INFO[l]["gb"] for l in ls), 1),
                  "dl_gb": round(sum(MODEL_INFO[l]["gb"] for l in miss), 1)}
        if ls and not miss:
            full.append(k)
    mine = chosen if chosen in full else next(
        (k for k in reversed(MODEL_SETS) if k in full and not out[k]["same"]),
        "")
    for k in MODEL_SETS:
        out[k]["state"] = ("yours" if k == mine else
                           "installed" if k in full else "download")
    out["mine"], out["every"] = mine, "everything" in full
    return out


def offer_set_labels(pulled=None) -> list:
    """What the More-models card may offer from the sets (6b405, 6b312's
    rule): what is missing from the person's own set, the one they picked,
    else the largest set that is all here (so nothing). Never a bigger set."""
    st = model_sets_status(pulled)
    k = st["chosen"] or st["mine"]
    return list(st[k]["labels"]) if k else []


def _family_of(label: str) -> str:
    """Models that are versions of THE SAME THING. Role splits a family
    (6b258): a coder or a vision model is not an older sibling of the
    chat model, it does a different job, so it is never superseded by
    one."""
    base = label.split()[0]
    if "Coder" in label:
        return base + ":coder"
    if "Vision" in label or "LLaVA" in label:
        return "vision"
    return base


# who merges in combine mode — strongest first
MERGE_RANK = sorted((l for l in MODEL_ROUTES),
                    key=lambda l: -MODEL_INFO[l]["mem"])


def merge_pref_label() -> str:
    """The Gemma that will write the merge if it's on this machine (5.3,
    per Patrick: the largest Gemma 4 the machine can hold). '' when none
    is cached and fits. ONE definition on purpose (6b243): the handler
    uses it to put the merger LAST in the council roster and run_council
    uses it to pick the merger — if these two ever disagree, the roster
    ordering optimisation warms the wrong engine."""
    for pref in MERGE_PREFS:
        if model_cached(pref) and model_fits_memory(pref):
            return pref
    return ""


def budget_label() -> str:
    """Human note about what the ladder was sized against."""
    v = gpu_vram_bytes()
    return ("%d GB VRAM" % round(v / 1e9)) if v else ""


def _pc_cpu_name() -> str:
    """A PC's processor, shortly (6b317, from the Windows sweep): it read
    "INTEL64", "AMD64" or "ARMV8", Windows' architecture caption. The
    name Windows keeps is e.g. "13th Gen Intel(R) Core(TM) i7-13700H"."""
    brand = ""
    try:
        import winreg
        with winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE,
                            r"HARDWARE\DESCRIPTION\System\CentralProcessor"
                            r"\0") as k:
            brand = str(winreg.QueryValueEx(k, "ProcessorNameString")[0])
    except Exception:
        pass
    b = re.sub(r"\((?:R|TM)\)|\bCPU\b|\bProcessor\b|\d+(?:st|nd|rd|th) Gen\b",
               " ", brand.split("@")[0])
    b = " ".join(b.split())
    for rx, fmt in ((r"(Threadripper)\b", "%s"),
                    (r"Core ?(i\d)\b", "CORE %s"),
                    (r"Core (Ultra \d)\b", "CORE %s"),
                    (r"(Ryzen(?: AI)?(?: Max\+?)?(?: \d{1,3})?)\b", "%s"),
                    (r"(Snapdragon(?: X)?(?: Elite| Plus)?)", "%s"),
                    (r"(Xeon|Celeron|Pentium|Atom|EPYC)\b",
                     "%s")):
        m = re.search(rx, b, re.I)
        if m:
            return (fmt % m.group(1)).upper()[:18]
    if b:
        return b.upper()[:18]
    return (platform.processor() or "PC").split()[0].upper()[:18]


def chip_name() -> str:
    """Short marketing name of the CPU: 'M4 PRO', 'CORE I7', etc."""
    if IS_WIN:
        try:
            gpu = subprocess.run(
                ["nvidia-smi", "--query-gpu=name",
                 "--format=csv,noheader"], capture_output=True, text=True,
                timeout=2,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
            ).stdout.strip().splitlines()
            if gpu:      # "NVIDIA GeForce RTX 4090" -> "RTX 4090"
                name = gpu[0].replace("NVIDIA", "").replace("GeForce", "")
                return " ".join(name.split()).upper()[:18]
        except Exception:
            pass
        return _pc_cpu_name()
    try:
        brand = subprocess.run(["sysctl", "-n", "machdep.cpu.brand_string"],
                               capture_output=True, text=True,
                               timeout=2).stdout.strip()
    except Exception:
        brand = ""
    if not brand:
        return "HARDWARE"
    if brand.startswith("Apple "):          # "Apple M4 Pro" -> "M4 PRO"
        return brand[6:].upper()
    m = re.search(r"(Core\(TM\)|Core)\s+(i\d)", brand)
    if m:                                    # long Intel string -> "CORE I7"
        return f"CORE {m.group(2)}".upper()
    return brand.split("@")[0].strip()[:18].upper()


def build_model_rows() -> str:
    """Sidebar rows grouped by HARDWARE CLASS, strongest last-to-first
    within a class. Models that cannot fit this machine's memory are not
    rendered at all — every visitor sees only their own ladder, with the
    best option of each class present. Models the platform can't run
    (MLX-only on Intel/Windows) stay visible but greyed."""
    out = []
    for key, title, _ceil in HW_CLASSES:
        members = [(l, i) for l, i in MODEL_INFO.items()
                   if hw_class(i["mem"] / 1e9) == key
                   and model_fits_machine(l)]
        if not members:
            continue
        members.sort(key=lambda p: -p[1]["mem"])   # strongest first
        out.append(f'  <div class="group-label mlx">{title}</div>')
        for label, info in members:
            ok = SUPPORTED[label]
            out.append(
                f'  <div class="model{"" if ok else " unsupported"}"'
                f' data-model="{label}">'
                f'<span class="ico">{info["icon"]}</span>{label}'
                + ("" if ok else
                   '<span class="memtag">APPLE SILICON ONLY</span>')
                + f'<span class="size">{info["size"]}</span></div>')
    return "\n".join(out)


def _mem_available():
    """Bytes of comfortably-usable RAM right now, or None if unknown."""
    if not HAS_PSUTIL:
        return None
    return psutil.virtual_memory().available


def model_fits_memory(label: str) -> bool:
    # the giant gate holds at run time too (6b307): tiers, the merger
    # and every fallback ask this before starting a model
    if model_is_giant(label) and not giants_on():
        return False
    if not giant_fits_here(label):
        return False               # "no limits" can't make a PC a workstation
    if no_limits():
        # "disobey the limits": admission stands down entirely — a 70B on
        # a 48GB Mac swaps hard, and that is the explicit ask
        return True
    # `available` on macOS omits reclaimable file cache — right after an
    # 18.5 GB model download the cache ATE the headroom and the freshly
    # installed flagship was refused admission (seen live). What the OS
    # will actually hand a wiring allocation is closer to total - used.
    avail = _mem_available()
    if HAS_PSUTIL:
        vm = psutil.virtual_memory()
        avail = max(avail or 0, vm.total - vm.used)
    need = MODEL_MEM_BYTES.get(label)
    if avail is None or need is None:
        return True  # unknown — don't cry wolf
    kind, target = MODEL_ROUTES.get(label, (None, None))
    if kind == "mlx" and _engine_up(target):
        return True  # already resident and serving
    if kind == "ollama" and not IS_MAC:
        # the part on the graphics cards costs no system RAM (6b315): an
        # 85 GB model on a 96 GB card was refused on a 128 GB PC
        need = _ram_part(label)
        if need == 0:
            return True
    # Real footprints run above the estimate — a "44 GB" 70B was measured at
    # 49.7 GB and got OOM-killed — so demand real headroom, and never allow a
    # model that needs most of the machine even when RAM looks free.
    total = psutil.virtual_memory().total if HAS_PSUTIL else 0
    if total and need > total * 0.8:
        return False
    # 1.5x, not 1.25x: the KV cache and activations grow DURING generation,
    # and a 26B admitted at 1.25x OOM'd 97s into its answer on a busy
    # machine. Admission must survive the whole reply, not just the load.
    # MoE models get 1.3x — only a few billion parameters activate per
    # token, so their runtime overhead is a fraction of a dense model's.
    return need * _mem_factor(label) < avail

# THE PLACE A WEATHER QUESTION NAMES (6b317, found asking a Windows VM
# "what's the weather in Chicago right now"): the place was everything
# after "weather in", so wttr.in and the geocoder were asked about
# "Chicago right now" and the answer had no live data; only a zip code
# had ever been tested. Time words now come out wherever they sit. And
# wttr.in turns ANY string into some real town (review: "What's" is
# Pesaro, "running" is in Norway), so a wrong guess answers with another
# city's weather, worse than none: only a slot that reads as a place is
# taken. "Near me", "outside" and a question naming no place at all mean
# the home area (WX_HERE).
WX_HERE = "~here"
_WX_WHEN = re.compile(
    r"\b(?:right now|now|currently|at the moment|over the weekend|"
    r"(?:today|tonight|tomorrow)(?:'s|s)?"
    r"(?: (?:morning|afternoon|evening|night))?|"
    r"(?:this|next|the) (?:weekend|week|month)(?:'s)?|"
    r"(?:this|next) (?:morning|afternoon|evening)|"
    r"(?:in|for|over) the (?:morning|afternoon|evening|next few days|"
    r"coming days|days ahead|week ahead)|at night|"
    r"(?:in|for) (?:a bit|an hour|a few hours|\d+ (?:hours?|days?))|"
    r"(?:on|this|next) (?:mon|tues|wednes|thurs|fri|satur|sun)day(?:'s)?"
    r"(?: (?:morning|afternoon|evening|night))?|"
    r"(?:in|this|next) (?:january|february|march|april|june|july|august|"
    r"september|october|november|december|spring|summer|fall|autumn|"
    r"winter))\b"
    r"|\b(?:mon|tues|wednes|thurs|fri|satur|sun)day\s*$", re.I)
# words no place name is made of
_WX_NOT_PLACE = set("""a an me my our your you i we us it it's its is are was
be been being can could would will should please tell give show get check know
find see what what's whats how how's hows where where's wheres when why who
which there here outside local current general vs versus going gonna
supposed looking like any some do does did""".split())
# ...and the ones that before "weather" describe it, not place it
_WX_DESCRIBE = set("""nice good bad great best worst severe extreme hot cold
warm cool wet dry rainy stormy sunny cloudy windy snowy crazy weird perfect
beautiful lovely awful terrible typical usual normal average fair foul
inclement winter summer spring fall autumn the high low max min daily hourly
weekly extended 5-day 7-day 10-day 14-day current local""".split())
_WX_NOT_BEFORE = _WX_NOT_PLACE | _WX_DESCRIBE
# ...and after a bare "weather" ("weather report")
_WX_NOT_AFTER = _WX_NOT_PLACE | set("""report reports update updates alert alerts
warning warnings radar map maps app apps tips channel station forecast
forecasts conditions news today the""".split())
# what "for" means when it isn't a place
_WX_ACTIVITY = set("""running run hiking hike skiing biking cycling golf golfing
fishing surfing camping sailing walking walk jogging swimming driving drive
flying flight travel traveling travelling boating climbing kayaking
snowboarding beach picnic wedding game party parade concert trip commute
event outdoors""".split())
# a generic setting after "the" is no place: "at the beach", "the game"
_WX_GENERIC = set("""city mountains mountain beach park area neighborhood
neighbourhood suburbs country countryside woods lake desert coast north south
east west region state world game match wedding party parade trip weekend
week office airport""".split())
_WX_SELF = re.compile(r"\b(?:near|around|by) (?:me|here|us)\b|\b(?:in|for) "
                      r"(?:my|our) (?:area|location|neighbou?rhood|city|town)"
                      r"\b|\b(?:outside|around here|at home|local|at my "
                      r"(?:place|house|apartment))\b", re.I)
_WX_FILLER = set("""like be going gonna looking look is it will to for
the in out there here supposed today now forecast forecasts temperature
temperatures""".split())
# a sales or rate "forecast" is no weather question
_WX_NOT_WX = re.compile(r"\b(?:sales|revenue|earnings|budget|economic|market|"
                        r"stock|price|inflation|rates?|demand|financial|"
                        r"traffic|cash ?flow)\b", re.I)


def _wx_words_ok(cand: str, stop: set, most: int = 5) -> bool:
    words = re.findall(r"[\w'.-]+", cand.lower())
    return (0 < len(words) <= most and not stop.intersection(words)
            and any(ch.isalpha() for ch in cand))


def weather_place(q: str) -> str:
    """The place in a weather question; WX_HERE for the home area; ""
    when the question names something that isn't a place."""
    q = q.replace("\u2019", "'")
    m = re.search(r"\b(\d{5})\b", q)
    # a bare 5-digit zip is ambiguous worldwide — 11221 alone resolved to
    # Vilnius, Lithuania; ',us' pins it to Brooklyn
    if m:
        return m.group(1) + ",us"
    if _WX_NOT_WX.search(q) or not re.search(
            r"\b(?:weather|forecast|temperatures?)\b", q, re.I):
        return ""
    s = " ".join(_WX_WHEN.sub(" ", q).split()).strip(" ?.!,")
    kw = r"\b(?:weather|forecast|temperatures?)\b"
    loc = None
    m = re.search(kw + r".*?\b(in|for|at|near|around)\s+(.+)$", s, re.I)
    if m:
        prep, loc = m.group(1).lower(), m.group(2)
        # what the time words left: "for [tomorrow] in New York"
        while True:
            m2 = re.match(r"(in|for|at|near|around)\s+(.+)$", loc, re.I)
            if not m2:
                break
            prep, loc = m2.group(1).lower(), m2.group(2)
        # what follows the place: "Chicago and", "Chicago going to be"
        # (lower case: "Portland, OR" keeps its state)
        loc = re.split(r"\s+(?:and|or|&|vs\.?|versus|going|gonna|supposed|"
                       r"looking|be|like|will|is|are|for|this|next|on|to|so|"
                       r"because|since|if|when|with|without|in|at|near|"
                       r"around|during|over|by|from|using)\b", loc,
                       maxsplit=1)[0].strip(" ,?.!'\"")
        low = loc.lower().split()
        if not low:
            loc = None
        elif low[0] in _WX_ACTIVITY or (prep == "for" and low[0] in (
                "my", "our", "your", "a", "an", "this", "that")):
            return ""
        elif low[0] == "the" and (len(low) < 2 or low[1] in _WX_GENERIC or (
                prep in ("at", "for") and not loc.split()[1][:1].isupper())):
            return ""
        elif not _wx_words_ok(loc, _WX_NOT_PLACE):
            return WX_HERE if _WX_SELF.search(q) else ""
    if loc is None:
        m = re.match(r"(.*?)" + kw + r"\s*(.*)$", s, re.I)
        before = m.group(1).strip() if m else ""
        after = m.group(2).strip() if m else ""
        # "what's Boston's weather", "NYC weather"
        before = re.sub(r"^(?:(?:what|how)(?:'s| is| will)?|whats|hows|"
                        r"(?:can|could) you (?:check|tell me|give me)|tell me|"
                        r"give me|show me|check|get)\b\s*(?:the\b\s*)?", "",
                        before, flags=re.I)
        before = re.sub(r"'s$", "", before.strip())
        if set(re.findall(r"[\w'.-]+", before.lower())) <= _WX_DESCRIBE:
            before = ""                 # "nice weather", "the high temperature"
        # "like", "going to be", "is it": nothing that names anything
        rest = [w for w in re.findall(r"[\w'.-]+", after.lower())
                if w not in _WX_FILLER]
        if before and _wx_words_ok(before, _WX_NOT_BEFORE, 4):
            loc = before
        elif rest and not before and _wx_words_ok(after, _WX_NOT_AFTER, 3):
            loc = after                 # "weather Denver"
        elif _WX_SELF.search(q) or (not before and not rest):
            return WX_HERE
        else:
            return ""
    return loc.strip(" ,?.!'\"")


def weather_snippets(q: str):
    """Real numbers for weather questions. Generic web snippets for
    'weather in 11221' returned Moscow forecasts and kids' videos (seen
    live) — honest models reported garbage, confident ones invented a
    forecast. wttr.in resolves a zip or place name to actual conditions,
    no API key. None on any failure — the caller falls back to search."""
    loc = weather_place(q)
    if loc == WX_HERE:
        # "what's the weather", "near me": the home area, when one is set
        loc = home_area()
    if not loc or len(loc) > 60:
        return None
    # weekday names on every forecast line — a Friday "this weekend"
    # ask once shipped Saturday only because mapping bare dates to
    # weekdays was left to the model (6b265, judged)
    def _wd(datestr):
        try:
            return time.strftime(
                "%A", time.strptime(datestr, "%Y-%m-%d"))
        except Exception:
            return datestr
    # "this weekend" means the COMING Saturday and Sunday (6b272,
    # judged: asked at 2 AM Monday, the answer relived the weekend
    # that had just ended). wttr.in stops at three days, so a
    # weekend ask goes straight to the 7-day rung and reports today
    # plus those two days, labeled so nothing needs date math.
    weekend = bool(re.search(r"\bweekend\b", q, re.I))
    def _weekend_dates(tzname=""):
        # computed on the LOCATION's calendar (6b273): a Brooklyn
        # weekend asked from Tokyo is still Brooklyn's Saturday
        import datetime as _dt
        try:
            from zoneinfo import ZoneInfo
            now = _dt.datetime.now(ZoneInfo(tzname)) if tzname \
                else _dt.datetime.now()
        except Exception:
            now = _dt.datetime.now()
        ahead = (5 - now.weekday()) % 7        # days until Saturday
        if ahead == 0 and now.hour >= 18:      # Saturday evening -> next
            ahead = 7
        sat = now + _dt.timedelta(days=ahead)
        sun = now + _dt.timedelta(days=ahead + 1)
        return (sat.strftime("%Y-%m-%d"), sun.strftime("%Y-%m-%d"))
    try:
        if weekend:
            raise ValueError("weekend: 7-day rung")
        with urllib.request.urlopen(
                "https://wttr.in/%s?format=j1" % urllib.parse.quote(loc),
                timeout=8) as r:
            d = json.load(r)
        cur = d["current_condition"][0]
        area = d["nearest_area"][0]
        name = "%s, %s" % (area["areaName"][0]["value"],
                           area["region"][0]["value"])
        # wttr.in names the area of its nearest station: Chicago came back
        # as "Mccormickville, Illinois", and the model, told that, would
        # not call it Chicago's weather (6b317). The place asked for leads,
        # a zip too: 11221 came back as "Adelphi, New York" (6b318)
        asked = (loc[:-3] if loc.endswith(",us") else " ".join(
            w[:1].upper() + w[1:] for w in loc.split()))
        name = "%s (station: %s)" % (asked, name)
        # SANITY (6b270, judged 2.0: "87°F and sunny right now" at
        # 3:30 AM — a stale daytime observation served as current,
        # above the day's own high). A reading older than two hours
        # or hotter than today's forecast high is not "right now";
        # this rung steps aside and the next one answers.
        # wttr.in stopped sending localObsDateTime (seen 2026-09, 6b317),
        # which left the age check and the night check below on the
        # host's clock. observation_time, in UTC, dates the reading; the
        # place's longitude gives its sun time (and the old local-time
        # math was hours off for a place in another time zone anyway).
        _age, _hr, _seen = 0.0, _venue_now().tm_hour, "just now"
        try:
            _ot = time.strptime(str(cur.get("observation_time")), "%I:%M %p")
            _g = time.gmtime()
            _age = float(((_g.tm_hour - _ot.tm_hour) * 3600
                          + (_g.tm_min - _ot.tm_min) * 60) % 86400)
            if _age > 86400 - 1800:        # a clock running a little fast
                _age = 0.0
            _seen = "%d min ago" % (_age // 60)
            _hr = int((_ot.tm_hour + _ot.tm_min / 60.0
                       + float(area["longitude"]) / 15) % 24)
        except Exception:
            pass
        _hi = float(d["weather"][0]["maxtempF"]) if d.get("weather") else 999
        if _age > 2 * 3600 or float(cur["temp_F"]) > _hi + 3:
            raise ValueError("stale or impossible reading")
        _desc = cur["weatherDesc"][0]["value"].strip()
        if _hr < 6 or _hr >= 20:
            # no sun at night: the feed says "Sunny" for a clear sky
            _desc = re.sub(r"\bsunny\b", "clear", _desc, flags=re.I)
        out = ["LIVE WEATHER for %s (source: wttr.in, observed %s):"
               % (name, _seen),
               "Right now: %s°F (feels like %s°F), %s, wind %s mph, "
               "humidity %s%%" % (
                   cur["temp_F"], cur["FeelsLikeF"], _desc,
                   cur["windspeedMiles"], cur["humidity"])]
        for day in d.get("weather", [])[:3]:
            out.append("%s %s: high %s°F / low %s°F, %s" % (
                _wd(day["date"]), day["date"],
                day["maxtempF"], day["mintempF"],
                day["hourly"][4]["weatherDesc"][0]["value"]))
        _tl_search.weather_src = {"t": "Live weather — " + name.split(" (station")[0],
                                  "u": "https://wttr.in/%s"
                                       % urllib.parse.quote(loc)}
        return "\n".join(out)
    except Exception:
        pass
    # SECOND RUNG (6b266, judged 2.0: wttr.in died silently one night
    # and the model invented "71°F and sunny" at 10:30 PM). Same
    # two-endpoint ladder the venue data wears: open-meteo is keyless
    # and geocodes through the same home-biased _geocode.
    try:
        # a bare 5-digit zip is ambiguous worldwide — "11221" alone
        # geocoded to VILNIUS (seen live, 6b272); the country hint
        # the first rung carries as ",us" becomes Nominatim's ", USA"
        g = _geocode(loc.replace(",us", ", USA"))
        if not g:
            return None
        with urllib.request.urlopen(
                "https://api.open-meteo.com/v1/forecast?"
                "latitude=%s&longitude=%s"
                "&current=temperature_2m,apparent_temperature,"
                "weather_code,wind_speed_10m,relative_humidity_2m,is_day"
                "&daily=temperature_2m_max,temperature_2m_min,"
                "weather_code&temperature_unit=fahrenheit"
                "&wind_speed_unit=mph&timezone=auto&forecast_days=%d"
                % (g["lat"], g["lon"], 9 if weekend else 3),
                timeout=8) as r:
            d = json.load(r)
        _WMO = ((0, "clear"), (3, "partly cloudy"), (48, "fog"),
                (57, "drizzle"), (67, "rain"), (77, "snow"),
                (82, "rain showers"), (86, "snow showers"),
                (99, "thunderstorms"))
        def _sky(code):
            for hi, word in _WMO:
                if code <= hi:
                    return word
            return "mixed"
        cur = d["current"]
        dl = d.get("daily", {})
        _hi = (dl.get("temperature_2m_max") or [999])[0]
        if float(cur["temperature_2m"]) > float(_hi) + 3:
            return None            # impossible "now"; honesty branch
        _skyw = _sky(cur["weather_code"])
        if not cur.get("is_day", 1) and _skyw == "clear":
            _skyw = "clear (night)"
        # feels-like within reason (6b272, judged: 77°F "feels like"
        # at 72°F/89% humidity) — the apparent-temperature formula
        # barely departs from the air temperature below 80°F
        if float(cur["temperature_2m"]) < 80 and abs(
                float(cur["apparent_temperature"])
                - float(cur["temperature_2m"])) > 6:
            cur["apparent_temperature"] = cur["temperature_2m"]
        out = ["LIVE WEATHER for %s (source: open-meteo, observed %s):"
               % (g.get("name", loc), str(cur.get("time") or "now")),
               "Right now: %.0f°F (feels like %.0f°F), %s, wind "
               "%.0f mph, humidity %s%%" % (
                   cur["temperature_2m"], cur["apparent_temperature"],
                   _skyw, cur["wind_speed_10m"],
                   cur["relative_humidity_2m"])]
        _tl_search.weather_src = {"t": "Live weather — " + str(
            g.get("name", loc))[:60], "u": "https://open-meteo.com/"}
        _tzn = str(d.get("timezone") or "")
        if _tzn:
            _tl_search.tz = _tzn
            _tl_search.tz_place = str(g.get("name", loc)).split(",")[0][:40]
        _sat, _sun = _weekend_dates(_tzn) if weekend else ("", "")
        _today = time.strftime("%Y-%m-%d", _venue_now(_tzn))
        for i, ds in enumerate(dl.get("time", [])):   # the request bounds it
            if weekend and ds not in (_today, _sat, _sun):
                continue
            _lab = ("today" if ds == _today else
                    "this coming Saturday" if ds == _sat else
                    "this coming Sunday" if ds == _sun else _wd(ds))
            out.append("%s %s: high %.0f°F / low %.0f°F, %s" % (
                _lab, ds, dl["temperature_2m_max"][i],
                dl["temperature_2m_min"][i],
                _sky(dl["weather_code"][i])))
        return "\n".join(out)
    except Exception:
        return None


_search_cache = profile_cache(
    "_search_cache", {"query": "", "data": "", "timestamp": 0.0})
_search_lock = threading.Lock()

# Auto-search: local models have a training cutoff and no clock, so anything
# asking about *now* gets live snippets folded in before the model answers.
_FRESH_WORDS = (
    "today", "tonight", "right now", "currently", "current", "latest",
    "recent", "recently", "this week", "this month", "this year",
    "yesterday", "tomorrow", "so far", "up to date", "as of",
    "news", "headline", "weather", "forecast", "temperature",
    "price", "stock", "market", "score", "standings", "election",
    "release date", "released", "just announced", "who won", "what happened",
    "trending", "live", "update", "version",
    # LOCAL / LIVE FACTS — a business-hours question fabricated opening
    # times and a 555 phone number (seen live). Over-searching is cheap;
    # an invented phone number is not.
    "hours", "open now", "near me", "phone number", "address",
    "menu", "reservation", "showtimes", "tickets", "schedule",
    "this weekend", "in stock", "wait time", "happening", "closes",
    "closing time", "opening time",
)
# arranging/booking something real: without live data the model invents
# named retreats with cohort dates and prices ("Soulstice", "Nomad Nest"
# — seen live). Needs BOTH an arranging verb and a bookable noun, so
# "recommend a sorting algorithm" stays local. Named so the answer path
# can also route these to the DEEP search — real program names and
# prices live in listing pages, not 200-char snippets.
_PLACE_NOUNS = (r"(retreats?|hostels?|hotels?|"
                r"resorts?|airbnbs?|tours?|trips?|flights?|restaurants?|"
                r"bars?|caf[eé]s?|classes|workshops?|events?|festivals?|"
                r"concerts?|spas?|gyms?|studios?|coworking|spots?|places?|"
                r"joints?|shops?|diners?|delis?|bakeries|pizzerias?|"
                r"venues?|bodegas?|pubs?|clubs?|breweries|taquerias?|"
                r"museums?|galleries|parks?|markets?|bookstores?|"
                # the FOOD ITSELF is how people actually ask — "best
                # pizza in williamsburg" answered from memory and put
                # pizza on Lilia's menu (it's a pasta place, seen live)
                r"pizza|slices?|tacos?|coffee|ramen|sushi|burgers?|"
                r"bagels?|brunch|breakfast|lunch|dinner|cocktails?|"
                r"drinks?|bbq|barbecue|wings|dumplings|pho|falafel|"
                r"shawarma|pastrami|donuts?|desserts?|ice\s+cream|"
                r"beer|wine|espresso|matcha|pastries|croissants?)")

# "what's a good bar in bushwick" carries no verb at all — it went
# UNSEARCHED and the model invented three bars from memory (seen live).
# A quality word plus a place noun is just as much a recommendation ask.
_ASKY_RX = re.compile(
    r"\b(good|best|great|favorite|favourite|top|cool|nice|solid|decent|"
    r"worth|must[- ]?(see|try|visit)|underrated|hidden\s+gem)\b.*?"
    + _PLACE_NOUNS + r"\b", re.I | re.S)

# A HEALTH QUESTION ABOUT A CONSUMABLE IS NOT A VENUE ASK (6b247, seen
# live): "is a glass of wine a day actually good for you" matched
# _ASKY_RX via "good…wine" — wine is a _PLACE_NOUN so "best wine in
# bushwick" searches properly — and the whole places machinery engaged:
# the [[PLACES]] extraction read the ANSWER'S SECTION HEADINGS as venue
# names and the geocoder pinned them, because "Brain" is a real commune
# in France. When the query is about the body, none of it applies.
_NOT_PLACEY_RX = re.compile(
    r"\b(bad|good|healthy|unhealthy|safe|harmful|dangerous|worse|better)"
    r"\s+for\s+(you|me|your|my|health)\b|"
    r"\bhealth(y|ier|iest)?\b|\bcalories\b|\bhangovers?\b|"
    r"\b(why|how)\s+(is|are|does|do)\b.{0,40}\b(bad|harm|hurt|affect)",
    re.I)

_BOOKING_RX = re.compile(
    r"\b(arrange|book|recommend|suggest|find|plan|help\s+me\s+"
    r"(find|pick|choose))\b.*\b(retreats?|hostels?|hotels?|"
    r"resorts?|airbnbs?|tours?|trips?|flights?|restaurants?|"
    r"bars?|caf[eé]s?|classes|workshops?|events?|festivals?|"
    r"concerts?|spas?|gyms?|studios?|coworking|spots?|places?|"
    r"joints?|shops?|diners?|delis?|bakeries|pizzerias?|"
    r"venues?|bodegas?)\b", re.S)

_FRESH_PATTERNS = (
    re.compile(r"\b20[2-9]\d\b"),                 # a specific modern year
    re.compile(r"\bwho\s+is\s+the\s+(current|new)\b"),
    re.compile(r"\bhow\s+much\s+(is|does|are)\b"),
    re.compile(r"\bwhat('?s| is)\s+(the\s+)?(latest|newest|current)\b"),
    re.compile(r"\bis\s+there\s+(a|an)\s+new\b"),
    re.compile(r"\b(out|available|released)\s+yet\b"),
    re.compile(r"\b(is|are|when)\b.*\b(open|closed?)\b"),
    re.compile(r"\bwhat\s+time\b.*\b(open|close)"),
    _ASKY_RX,
    _BOOKING_RX,
)
# WORK THAT CARRIES ITS OWN CONTEXT: rewriting, translating, coding,
# creative writing and pure math need no web (6b224) — everything else
# that ASKS something gets grounded.
_SELF_CONTAINED = re.compile(
    r"\b(translate|rewrite|reword|paraphrase|proofread|summari[sz]e|"
    r"refactor|debug|fix\s+(this|my)|explain\s+(this|my)\s+(code|error)|"
    r"write\s+(me\s+)?(a|an|some)?\s*(poem|story|song|essay|email|"
    r"letter|caption|joke|script|cover\s+letter)|"
    r"this\s+(code|text|file|function|error|snippet|draft)|"
    r"my\s+(code|essay|draft|resume|cv|email))\b", re.I)

# A PLACE QUESTION IS ALWAYS A LIVE QUESTION (6b237). "late night
# restaurants in 11221" opens with no question word and ends in no '?',
# so the grammar test below said don't search — and the answer came back
# as a polite apology for having no data, on the one class of question
# where a model's memory is guaranteed to be useless. Hours, openings,
# closures and new arrivals are exactly what training data cannot hold,
# so a venue word, a US zip, or an explicit "near/open now" searches on
# its own regardless of how the sentence is shaped.
_VENUE_RX = re.compile(
    r"\b(restaurants?|bars?|pubs?|cafes?|cafés?|coffee|diners?|eater(y|ies)|"
    r"eats|takeout|takeaway|brunch|bakery|bakeries|delis?|bodegas?|"
    r"pizza|sushi|ramen|tacos?|burgers?|noodles?|barbecue|bbq|"
    r"grocery|groceries|hotels?|motels?|hostels?|gyms?|barbers?|salons?|"
    # shops/stores/joints/venues are venue words too (6b265, measured:
    # "coffee shops near williamsburg" left _loc = "shops williamsburg",
    # the home bias missed, and Nominatim answered with VIRGINIA)
    r"shops?|stores?|joints?|venues?|"
    r"pharmac(y|ies)|hospitals?|clinics?|dentists?|bookstores?|"
    r"laundromats?|nightlife|nightclubs?|clubs?|breweries|brewery|"
    r"speakeas(y|ies)|dispensar(y|ies))\b", re.I)
_ZIP_RX = re.compile(r"\b\d{5}\b")
# what's-on questions: current movies, showtimes, live events. Kept
# narrow — "movies" alone would catch "best movies of all time".
_LISTINGS_RX = re.compile(
    r"(\b(movies?|films?)\b.{0,40}\b(playing|out|new|this\s+week(end)?|"
    r"theat(er|re)s?)\b|\bshowtimes?\b|\bin\s+theat(er|re)s?\b|"
    r"\bwhat'?s\s+(playing|showing)\b)", re.I)
# "do you have any photos?" — an explicit ask for something to LOOK at
_WANTS_IMAGES = re.compile(
    r"\b(photos?|pics?|pictures?|images?|screenshots?|diagrams?|"
    r"show\s+me|what\s+(does|do)\s+(it|they|that|this)\s+look\s+like|"
    r"look\s+like)\b", re.I)
_NEARBY_RX = re.compile(
    r"\b(near\s+(me|here|by)|nearby|around\s+here|walking\s+distance|"
    r"in\s+the\s+area|open\s+(now|late|today|tonight))\b", re.I)

# ASKS ABOUT THE WORLD: a question word, or an explicit request for
# facts about something. Deliberately broad — a grounded answer beats a
# remembered one, and the app shows its sources.
_WORLDLY_RX = re.compile(
    r"^\s*(who|what|whats|what's|when|where|which|why|how|is|are|does|"
    r"do|did|can|should|any)\b|"
    r"\b(tell me about|info on|details on|spec|specs|review|reviews|"
    r"rated|compare|versus|vs\.?|near me|around here|open now)\b", re.I)

# never search these — they're about the conversation, not the world
_NO_SEARCH = re.compile(
    r"^\s*(hi|hey|hello|thanks|thank you|ok|okay|cool|nice|sure|yes|no|"
    r"continue|go on|again|more|summarize|rewrite|translate|explain that|"
    r"write|draft|code|refactor|debug|fix)\b", re.I)


def strip_greeting(p: str) -> str:
    """'Yo is abes in bushwick open' -> 'is abes in bushwick open'.

    New Yorkers open with a greeting; it must never reach a search
    engine ("Yo is Abe's" was presented back as the place's NAME) nor
    the no-search guard, which fires on greeting-prefixed messages.
    """
    rx = re.compile(r"^(hey|hi|hello|yo+|ayo|yerr+|sup|wass?up|whats\s+"
                    r"(up|good)|good\s+(morning|afternoon|evening)|dawg|"
                    r"bro|fam|dude|man|homie)\b[\s,!.\u2014-]*", re.I)
    p = p.strip()
    # "yo yo yo" and "whats good dawg" stack greetings \u2014 peel until quiet
    for _ in range(4):
        q = rx.sub("", p)
        if q == p:
            break
        p = q
    return p


def needs_search(prompt: str) -> bool:
    """Heuristic: does answering this require information from after the
    model's training cutoff? Cheap and deliberately conservative."""
    if not HAS_SEARCH:
        return False
    p = strip_greeting(prompt)
    if len(p) < 8 or _NO_SEARCH.match(p):
        return False
    low = p.lower()
    if any(w in low for w in _FRESH_WORDS):
        return True
    if any(rx.search(low) for rx in _FRESH_PATTERNS):
        return True
    # 6b224, per Patrick ("make sure web search is enabled"): a real
    # question about the world searches, unless it's self-contained
    # work. This is what makes "what sound system does nowadays use"
    # get sources instead of an apology (seen live).
    if _SELF_CONTAINED.search(low):
        return False
    # a place question searches whatever grammar it arrives in — see
    # _VENUE_RX above. This runs AFTER the self-contained check so
    # "translate my restaurant menu" still stays local.
    if (_VENUE_RX.search(low) or _ZIP_RX.search(low)
            or _NEARBY_RX.search(low)):
        return True
    return bool(_WORLDLY_RX.search(p) or p.rstrip().endswith("?"))

# words that mean "same subject, different day" — they carry no entity
_REL_WORDS = frozenset("""
    tomorrow today tonight now weekend weekends monday tuesday wednesday
    thursday friday saturday sunday morning afternoon evening late later
    early weekday weekdays holiday holidays
""".split())

_FOLLOWUP_RX = re.compile(
    r"\b(what about|how about|and (on|the|for)\b|do they|are they|is it|"
    r"was it|it'?s|there|that place|the menu|the price|the hours|book it|"
    r"tomorrow|tonight|today|this weekend)\b", re.I)


# POINTS BACK AT THE CONVERSATION (6b238). "where can i find THIS in
# 11221?" is meaningless on its own, but _place_terms left "find 11221"
# behind — a verb and a zip code — so _entity_thin called it a query
# that names a thing and the follow-up never inherited its subject. It
# searched a bare zip and came back with apartment listings and crime
# stats for Bushwick (seen live, right after a funnel that had just
# settled on a sushi combo). A demonstrative with no noun of its own IS
# the signal that the subject is upstream.
_REFERS_BACK_RX = re.compile(
    r"\b(this|that|these|those|it|them|they|the same|that one|"
    r"the above|there)\b", re.I)


def _entity_thin(q: str) -> bool:
    """True when a query names no actual thing — "is it open tomorrow"
    boils down to relative-time words only, and "where can i find this"
    points at something said earlier."""
    if _REFERS_BACK_RX.search(q or ""):
        return True
    toks = [w for w in _place_terms(q).split() if w not in _REL_WORDS]
    return not toks


# a funnel pick, as the client records it: "Which format? → Sushi combo"
_FUNNEL_PICK_RX = re.compile(r"\s→\s(.+)$")


# conversational throat-clearing that must never reach a search engine
_PREAMBLE_RX = re.compile(
    r"^\s*(no,?\s+)?(i\s+meant|i\s+mean|actually|sorry,?|scratch\s+that|"
    r"nvm|never\s?mind|wait,?)[\s,:.-]+", re.I)


def _thread_terms(messages, avoid: str = "") -> str:
    """The entity of the most recent searchable USER turn — so a
    follow-up ("what about tomorrow?") inherits the place it's about
    instead of searching for the word 'tomorrow'.

    `avoid` is the query being built: BORROW ONLY WHAT IT LACKS (6b240).
    Taking the first four tokens instead handed back "any good bars
    clubs" from "any good bars or clubs open late/now in bushwick ny" —
    four generic words, with the only part that mattered truncated off
    the end. The search then had no location at all and returned
    Virginia Beach, San Diego and Bodrum (measured). What a follow-up
    needs from the thread is precisely the part it does not already say.
    """
    try:
        skip = set(re.findall(r"[a-z0-9'&-]+", (avoid or "").lower()))
        msgs = list(messages)[:-1]
        # A FINISHED FUNNEL IS THE SUBJECT (6b238). Its picks are stored
        # as ASSISTANT turns shaped "question → choice", so the user-turn
        # scan below never saw them: after a funnel settled on a sushi
        # combo, "where can i find this in 11221?" searched a bare zip
        # and came back with apartment listings and crime stats (seen
        # live). The picks are exactly what "this" means. Earliest first,
        # because those are the category ("Sushi") while the last ones
        # are trailing detail ("Water").
        picks = []
        for m in msgs[-14:]:
            hit = _FUNNEL_PICK_RX.search(str(m.get("content", ""))[:300])
            if hit:
                picks.append(hit.group(1).strip())
        if picks:
            words = []
            for p in picks[:3]:
                for w in re.findall(r"[a-z0-9'&-]+", p.lower()):
                    if (w not in _PLACE_FILLER and w not in words
                            and w not in skip):
                        words.append(w)
            if words:
                return " ".join(words[:4])
        for m in reversed(msgs):
            if m.get("role") != "user":
                continue
            c = strip_greeting(str(m.get("content", ""))[:300])
            toks = [w for w in _place_terms(c).split()
                    if w not in _REL_WORDS]
            if toks and (needs_search(c)
                         or _BOOKING_RX.search(c.lower())):
                # what the new query already says is not worth repeating;
                # the leftovers are the location it is missing
                fresh = [w for w in toks if w not in skip]
                return " ".join((fresh or toks)[:4])
    except Exception:
        pass
    return ""


# ------------------------------------------------------- managed engines
# The app can run its own model servers, so a fresh machine needs nothing
# but a double-click. Anything already listening (e.g. launchd agents or a
# separately-run Ollama) is left alone.
_managed_procs = []
_mlx_procs = {}  # label -> Popen, so idle engines can be freed individually
_engine_lock = threading.Lock()


def _port_in_use(port: int) -> bool:
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        s.settimeout(0.3)
        return s.connect_ex(("127.0.0.1", port)) == 0


def _free_port() -> int:
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        s.bind(("127.0.0.1", 0))
        return s.getsockname()[1]


# ANOTHER PERSON'S ENGINE IS NOT OURS (6b310, per Patrick: questions and
# chats must never reach another user). Engines listen on fixed loopback
# ports, and every account on the computer shares loopback. So on a Mac
# with two logins, the second person's ConcordeAI found the first
# person's Ollama or MLX engine already listening and sent it every
# prompt, with memory, name and attached files (or sent it to anything
# else squatting on the port). A listener counts only when it runs as
# this OS user, or on Linux and Windows as a system account (root, the
# "ollama" service user, LocalSystem): only the machine's administrator
# controls those, and the administrator can read everything anyway.
#
# THREE ANSWERS, not two: True, False, or None when the probe itself
# failed (lsof timing out under memory pressure, say). Only a definite
# False moves an engine; None refuses that one request instead, so a
# slow probe can never spawn a second copy of a 17 GB model.
_SYSTEM_UID_MAX = 500 if IS_MAC else 1000
_MINE_CACHE = {"ts": 0.0, "ports": None}


def _my_listen_ports():
    """Every TCP port a process we trust is listening on, or None when
    that can't be read. One lsof for all of them, reused for a second:
    the status screens ask about every model at once."""
    now = time.time()
    if _MINE_CACHE["ports"] is not None and now - _MINE_CACHE["ts"] < 1:
        return _MINE_CACHE["ports"]
    ports = None
    try:
        if os.path.exists("/proc/net/tcp"):
            # Linux names each socket's owner uid outright
            ports = set()
            for fn in ("/proc/net/tcp", "/proc/net/tcp6"):
                if not os.path.exists(fn):
                    continue
                with open(fn) as f:
                    next(f, None)
                    for ln in f:
                        c = ln.split()
                        uid = int(c[7])
                        if c[3] == "0A" and (uid == os.getuid()
                                             or uid < _SYSTEM_UID_MAX):
                            ports.add(int(c[1].rsplit(":", 1)[1], 16))
        elif not IS_WIN:
            # macOS lsof lists only this user's own processes, so a port
            # that is in use but missing here is someone else's
            r = subprocess.run(
                ["lsof", "-nP", "-a", "-iTCP", "-sTCP:LISTEN", "-u",
                 str(os.getuid()), "-Fn"],
                capture_output=True, text=True, timeout=4)
            if r.returncode in (0, 1):     # 1 = nothing listening at all
                ports = {int(m) for m in re.findall(
                    r"^n.*:(\d+)$", r.stdout, re.M)}
    except Exception:
        ports = None
    _MINE_CACHE.update(ts=now, ports=ports)
    return ports


def _listener_is_mine(port: int):
    """True, False, or None (couldn't tell). Only asked about a port
    something is listening on."""
    if IS_WIN:
        try:
            return _win_listener_mine(port)
        except Exception:
            return None
    ports = _my_listen_ports()
    if ports is None:
        return None
    return port in ports


def _engine_up(port) -> bool:
    """An engine of OURS answers on this port. The status screens and
    the "already loaded" shortcuts ask this, never plain port-in-use: a
    port held by another account's engine is not a loaded model here."""
    return bool(port) and _port_in_use(port) and _listener_is_mine(port) is True


def _win_listener_mine(port: int):
    """Windows: full DOMAIN\\user names, compared whole (a local 'john'
    and CORP\\john are different people). None when an owner can't be
    read, which is what a non-elevated app gets for LocalSystem."""
    flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
    ok = {"nt authority\\system", "nt authority\\local service",
          "nt authority\\network service"}
    users = set()
    if HAS_PSUTIL:
        ok.add(psutil.Process(os.getpid()).username().lower())
        for c in psutil.net_connections("tcp"):
            if (c.laddr and c.laddr.port == port
                    and c.status == psutil.CONN_LISTEN):
                try:
                    users.add(psutil.Process(c.pid).username().lower())
                except psutil.AccessDenied:
                    # a service's owner can't be read without elevation,
                    # every time: "can't tell" left no local model working
                    # for good (6b317, from the Windows sweep). Not ours,
                    # then: ours starts on a free port, and that one never
                    # sees anyone else's questions.
                    users.add("?unreadable")
                except psutil.NoSuchProcess:
                    continue
                except Exception:
                    return None
    else:
        import csv
        me = subprocess.run(["whoami"], capture_output=True, text=True,
                            timeout=6, creationflags=flags).stdout
        ok.add(me.strip().lower())
        out = subprocess.run(["netstat", "-ano", "-p", "TCP"],
                             capture_output=True, text=True, timeout=6,
                             creationflags=flags).stdout
        pids = set()
        for ln in out.splitlines():
            c = ln.split()
            # the state column is translated on non-English Windows, so
            # a listener is recognised by its empty remote end instead
            if (len(c) >= 5 and c[1].endswith(":%d" % port)
                    and c[2] in ("0.0.0.0:0", "[::]:0")):
                pids.add(c[-1])
        for pid in pids:
            row = next(csv.reader([subprocess.run(
                ["tasklist", "/FI", "PID eq %s" % pid, "/V", "/FO", "CSV",
                 "/NH"], capture_output=True, text=True, timeout=6,
                creationflags=flags).stdout.strip()]), [])
            name = (row[6] if len(row) > 6 else "").strip().lower()
            if not name or name == "n/a":
                return None
            users.add(name)
    if not users:
        return None
    return users <= ok


def _own_engine_port(label: str) -> int:
    """The port for `label`'s MLX engine that THIS user owns. Someone
    else listening on the catalog port moves ours to a free one; every
    reader goes through MODEL_ROUTES, so the move is global. Can't tell
    = refuse this request rather than guess either way."""
    kind, port = MODEL_ROUTES[label]
    if _port_in_use(port):
        mine = _listener_is_mine(port)
        if mine is None:
            raise RuntimeError("couldn't check who runs this model's "
                               "engine; try again in a moment")
        if mine is False:
            port = _free_port()
            MODEL_ROUTES[label] = (kind, port)
            _RELOCATED.add(port)
            print(f"  another account holds {label}'s engine port — "
                  f"this user's runs on {port}")
    return port


_RELOCATED = set()     # engine ports we moved to: always ours to stop


OLLAMA_PORT = [11434]      # moves only when another account owns 11434


def ollama_url(path: str) -> str:
    """The URL of THIS user's Ollama. Raises rather than hand a prompt,
    a pull or a delete to an Ollama another account runs, or to one
    whose owner couldn't be checked."""
    port = OLLAMA_PORT[0]
    if _port_in_use(port):
        mine = _listener_is_mine(port)
        if mine is False:
            _spawn_ollama_serve()             # moves OLLAMA_PORT
            port = OLLAMA_PORT[0]
            mine = (_listener_is_mine(port) if _port_in_use(port)
                    else True)                # ours, still starting
        if mine is not True:
            raise RuntimeError(
                "Ollama on this computer is running for another account "
                "(or its owner couldn't be checked), so this app won't "
                "send it anything")
    return "http://127.0.0.1:%d%s" % (port, path)


def _has_mlx() -> bool:
    try:
        import mlx_lm  # noqa: F401
        return True
    except ImportError:
        return False


# the app can fetch its own Ollama engine (signed universal CLI) so a fresh
# machine — Intel or Apple silicon — needs zero manual installs
OLLAMA_TGZ_URL = "https://ollama.com/download/ollama-darwin.tgz"
# Windows portable build — bundles the CUDA runtime, so an NVIDIA GPU is
# used automatically with no extra setup
# Windows ships two builds: amd64 bundles the CUDA runtime, arm64 is
# CPU-only (Windows-on-ARM has no NVIDIA support).
#
# On Windows-on-ARM the app itself normally runs as *emulated x64*, because
# pythonnet (pywebview's backend) and ctranslate2 (faster-whisper) publish
# win_amd64 wheels only. (This note used to say `platform.machine()` reports
# this process's architecture; measured in the ARM64 VM, it reports the
# machine's, which is what this function wants. An x64 process is still
# told AMD64 by some calls, which would send an ARM laptop after the
# 1.5 GB CUDA build it can never use. Ollama is a separate process talked to
# over HTTP, so it should always be the *native* build — emulated UI, native
# inference.
def _win_native_machine() -> str:
    """Hardware architecture, seeing through x64/x86 emulation.
    6b317, found in a Windows 11 ARM VM: under x64 emulation Windows
    tells an x64 process it runs on AMD64 (IsWow64Process2 included), so
    the app fetched the 1.46 GB x64 Ollama, CUDA and all, to run emulated,
    instead of the 208 MB native ARM64 one. The system's own setting in
    the registry and Python's platform.machine() see the real chip."""
    try:
        import winreg
        k = winreg.OpenKey(
            winreg.HKEY_LOCAL_MACHINE,
            r"SYSTEM\CurrentControlSet\Control\Session Manager\Environment")
        if str(winreg.QueryValueEx(k, "PROCESSOR_ARCHITECTURE")[0]
               ).upper() == "ARM64":
            return "arm64"
    except Exception:
        pass
    if platform.machine().lower() in ("arm64", "aarch64"):
        return "arm64"
    try:
        import ctypes
        proc, native = ctypes.c_ushort(), ctypes.c_ushort()
        if ctypes.windll.kernel32.IsWow64Process2(
                ctypes.windll.kernel32.GetCurrentProcess(),
                ctypes.byref(proc), ctypes.byref(native)):
            return {0xAA64: "arm64", 0x8664: "amd64",
                    0x14C: "x86"}.get(native.value, "amd64")
    except Exception:
        pass  # pre-1709 Windows, or a non-Windows import — fall through
    return (os.environ.get("PROCESSOR_ARCHITEW6432")
            or os.environ.get("PROCESSOR_ARCHITECTURE")
            or platform.machine()).lower().replace("aarch64", "arm64")


IS_WIN_ARM = IS_WIN and _win_native_machine() == "arm64"
# true when an ARM box is running us through x64 emulation: the Python
# build itself says (platform.machine() reports the chip, not the build)
IS_WIN_EMULATED = IS_WIN_ARM and not sysconfig.get_platform().endswith(
    "arm64")
OLLAMA_ZIP_URL = ("https://github.com/ollama/ollama/releases/latest/download/"
                  + ("ollama-windows-arm64.zip" if IS_WIN_ARM
                     else "ollama-windows-amd64.zip"))
_MANAGED_BIN_DIR = os.path.join(app_dir(), "bin")


def _engine_exe(folder: str):
    """The Ollama binary in an engine folder: at its top, or one folder
    down (an archive that nests it; review of the port: 6b315's swap put
    such a folder in and then found no engine), or None."""
    exe = "ollama.exe" if IS_WIN else "ollama"
    top = os.path.join(folder, exe)
    if os.path.isfile(top):
        return top
    try:
        subs = sorted(os.listdir(folder))
    except OSError:
        return None
    for sub in subs:
        p = os.path.join(folder, sub, exe)
        if os.path.isfile(p):
            return p
    return None


def _ollama_bin():
    exe = "ollama.exe" if IS_WIN else "ollama"
    cands = [shutil.which("ollama"), _engine_exe(_MANAGED_BIN_DIR)]
    if IS_WIN:
        cands.append(os.path.join(
            os.environ.get("LOCALAPPDATA", ""), "Programs", "Ollama", exe))
    else:
        cands.append("/usr/local/bin/ollama")
    for c in cands:
        if c and os.path.exists(c):
            return c
    return None


def ollama_pulled_tags():
    """Set of pulled model names, or None if down. A bare name stands for
    its :latest pull only (6b314). It used to be added for EVERY tag, so
    the retired "DeepSeek R1" row (bare "deepseek-r1") read as on disk
    whenever deepseek-r1:8b or :671b was, and auto-clean deleted one of
    those instead."""
    try:
        with urllib.request.urlopen(
            ollama_url("/api/tags"), timeout=1.5
        ) as r:
            tags = json.loads(r.read().decode("utf-8")).get("models", [])
            names = {m.get("name", "") for m in tags}
            return names | {n[:-len(":latest")] for n in names
                            if n.endswith(":latest")}
    except Exception:
        return None


def model_cached(label, pulled=None):
    # NB: exact tag match only — ollama refuses "llama3.2:3b" even when
    # ":latest" is the same digest. Bare requested tags (e.g. "command-r")
    # still match because the pulled set includes bare names for :latest.
    # An unrouted label (an MLX-only row off Apple silicon, a Windows
    # giant on a Mac) is simply not here. Indexing MODEL_ROUTES blindly
    # made /api/setup and /api/tiers raise on every Windows PC (6b314).
    route = MODEL_ROUTES.get(label)
    if not route:
        return False
    kind, target = route
    if kind == "mlx":
        return mlx_model_cached(MLX_REPOS[label])
    if pulled is None:
        pulled = ollama_pulled_tags() or set()
    return target in pulled


def _hf_model_dir(repo: str) -> str:
    base = os.environ.get("HF_HOME") or os.path.expanduser("~/.cache/huggingface")
    return os.path.join(base, "hub", "models--" + repo.replace("/", "--"))


def mlx_model_cached(repo: str) -> bool:
    """True only when the weights are fully downloaded.

    hub-cache layout: snapshot symlinks appear per-file as each blob
    completes (config.json lands early!), and unfinished blobs sit in
    blobs/*.incomplete — so require the safetensors, every sharded part
    named by the index, and zero incomplete blobs.
    """
    d = _hf_model_dir(repo)
    snaps = glob.glob(os.path.join(d, "snapshots", "*", "config.json"))
    if not snaps:
        return False
    snap_dir = os.path.dirname(snaps[0])
    if not glob.glob(os.path.join(snap_dir, "*.safetensors")):
        return False
    if glob.glob(os.path.join(d, "blobs", "*.incomplete")):
        return False
    idx = os.path.join(snap_dir, "model.safetensors.index.json")
    if os.path.exists(idx):
        try:
            with open(idx, "r", encoding="utf-8") as f:
                parts = set(json.load(f)["weight_map"].values())
            if (not all(os.path.exists(os.path.join(snap_dir, p))
                        for p in parts)
                    and not _shards_complete(snap_dir)):
                return False
        except Exception:
            pass
    return True


def _shards_complete(snap_dir: str) -> bool:
    """Every part of the one shard series that IS in the snapshot
    (6b335). mlx-community's Ministral 3 14B ships two shards
    (model-0000N-of-00002) beside an index naming four (-of-00004), left
    from an earlier conversion; mlx_lm loads the files it finds, so the
    engine ran while this check called the model missing forever. A
    download that stopped between files still fails: its series has a
    gap."""
    series = {}
    for f in glob.glob(os.path.join(snap_dir, "*.safetensors")):
        m = re.fullmatch(r"(.+)-(\d+)-of-(\d+)\.safetensors",
                         os.path.basename(f))
        # a link whose blob never landed is no shard (review of 6b335)
        if not m or not os.path.isfile(f):
            return False
        series.setdefault((m.group(1), int(m.group(3))), set()).add(
            int(m.group(2)))
    return len(series) == 1 and all(
        got == set(range(1, n + 1)) for (_b, n), got in series.items())


def _dir_bytes(path: str) -> int:
    total = 0
    for root, _dirs, files in os.walk(path):
        for f in files:
            try:
                total += os.path.getsize(os.path.join(root, f))
            except OSError:
                pass
    return total


def _dir_bytes_real(path: str) -> int:
    """Bytes actually occupied, symlinks NOT followed. The hub cache
    stores one copy in blobs/ and links to it from snapshots/, so
    _dir_bytes (which follows links) reports a 9 GB model as 18 and would
    promise twice the disk an uninstall could free."""
    total = 0
    for root, _dirs, files in os.walk(path):
        for f in files:
            fp = os.path.join(root, f)
            try:
                if not os.path.islink(fp):
                    total += os.path.getsize(fp)
            except OSError:
                pass
    return total


def _spawn_mlx_engine(label: str, offline: bool = False) -> bool:
    """offline (the benchmark, 6b331): the engine may not ask the Hugging
    Face Hub anything. Loading a cached model otherwise checks the Hub
    for a newer revision, a network call the benchmark promises not to
    make; offline it reads the cache alone and can never download."""
    kind, port = MODEL_ROUTES[label]
    if kind != "mlx" or _port_in_use(port) or not _has_mlx():
        return False
    _retire_engine(label)      # never two copies of one model's weights
    logdir = log_dir()
    os.makedirs(logdir, exist_ok=True)
    log = open(os.path.join(logdir, f"managed-{port}.log"), "ab")
    proc = subprocess.Popen(
        [sys.executable, "-m", "mlx_lm", "server",
         "--model", MLX_REPOS[label], "--port", str(port)],
        stdout=log, stderr=log,
        env=(dict(os.environ, HF_HUB_OFFLINE="1", TRANSFORMERS_OFFLINE="1")
             if offline else None),
    )
    _managed_procs.append(proc)
    _mlx_procs[label] = proc
    print(f"  spawned MLX engine for {label} on port {port}")
    return True


def _stop_other_mlx(keep_label: str):
    """Keep one MLX model resident — each holds its full weights in RAM."""
    stopped = False
    for label, proc in list(_mlx_procs.items()):
        if label == keep_label or proc.poll() is not None:
            continue
        # THE EVICTION HAS TO ACTUALLY FINISH (6b239). This used to
        # terminate, wait 8s, and then drop the handle whatever happened
        # — so a big engine that was slow to die had its 17 GB still
        # wired when the next one spawned into it. The newcomer then
        # crawled or died, ensure_mlx_engine polled its full 180s, and
        # run_model's URLError retry did the whole thing again: Phi-4,
        # which loads in about 4s, took 336 SECONDS and produced nothing
        # (seen live). SIGTERM, then SIGKILL, and do not return until
        # the process is genuinely gone.
        try:
            proc.terminate()
            proc.wait(timeout=8)
        except Exception:
            try:
                print(f"  MLX engine for {label} ignored SIGTERM — killing")
                proc.kill()
                proc.wait(timeout=6)
            except Exception:
                pass
        _mlx_procs.pop(label, None)
        stopped = True
        print(f"  stopped idle MLX engine for {label}")
    if stopped:
        # Metal releases wired memory AFTER the process exits; spawning the
        # next engine immediately raced that teardown and died on startup
        # ("no MLX server answering" 6s after a swap, seen live). Give the
        # GPU allocator a beat to actually hand the memory back — and
        # rather than a flat guess, watch the memory come back, capped so
        # a machine that is busy for other reasons can't stall the run.
        time.sleep(1.0)
        if HAS_PSUTIL:
            _floor = psutil.virtual_memory().available
            _until = time.time() + 6.0
            while time.time() < _until:
                _now = psutil.virtual_memory().available
                if _now <= _floor:      # stopped climbing: teardown done
                    break
                _floor = _now
                time.sleep(0.5)
        else:
            time.sleep(1.5)


def ensure_mlx_engine(label: str, timeout: float = 180.0) -> bool:
    """Bring up the engine for `label` on demand, freeing the others first."""
    if "local-record" in TEST_HOOKS:
        _LOCAL_CALLS.append(("ensure", label))
        return True
    port = _own_engine_port(label)
    if _port_in_use(port):
        _stop_other_mlx(label)
        return True
    if not mlx_model_cached(MLX_REPOS[label]):
        return False
    _stop_other_mlx(label)
    if not _spawn_mlx_engine(label):
        return False
    deadline = time.time() + timeout
    while time.time() < deadline:
        # ours, not a squatter that grabbed the port while ours loaded
        if _port_in_use(port) and _listener_is_mine(port) is True:
            return True
        proc = _mlx_procs.get(label)
        if proc is not None and proc.poll() is not None:
            return False  # engine died on startup
        time.sleep(0.5)
    return False


def _spawn_ollama_serve() -> bool:
    """Start `ollama serve` if a binary exists and no Ollama of THIS
    user's is up. Another account's on 11434 doesn't count (6b310): ours
    then runs on a free port, on this user's own model store."""
    port = OLLAMA_PORT[0]
    if _port_in_use(port):
        mine = _listener_is_mine(port)
        if mine is True:
            if os.path.exists(_SWAP_TRIAL):
                _prove_if_serving(port)
            return True
        if mine is None:
            return False             # can't tell: never spawn a duplicate
        port = _free_port()
    _apply_staged_engine()
    b = _ollama_bin()
    if not b:
        return False
    logdir = log_dir()
    os.makedirs(logdir, exist_ok=True)
    log = open(os.path.join(logdir, "managed-ollama.log"), "ab")
    env = dict(os.environ, OLLAMA_HOST="127.0.0.1:%d" % port)
    if gpu_inventory()["igpu"]:
        # a Ryzen AI Max's graphics are "integrated", and Ollama leaves
        # an integrated GPU unused unless told to (6b315): without this
        # a Strix Halo ran every model on its CPU
        env["OLLAMA_IGPU_ENABLE"] = "1"
    _managed_procs.append(subprocess.Popen(
        [b, "serve"], stdout=log, stderr=log, env=env,
        creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
    ))
    OLLAMA_PORT[0] = port
    _managed_procs[-1]._cai_port = port
    if os.path.exists(_SWAP_TRIAL):
        # an engine swapped in at this start: the old one goes only once
        # this one answers (review of the port)
        ctx_thread(target=_prove_engine, args=(_managed_procs[-1], port),
                   bind=False, daemon=True).start()
    if port != 11434:
        _RELOCATED.add(port)
        try:                       # the boot reaper's note (see reap)
            with open(os.path.join(app_dir(), "run", "ollama-private"),
                      "w") as f:
                f.write("%d %d" % (_managed_procs[-1].pid, port))
        except OSError:
            pass
    print(f"  spawned ollama serve on port {port}")
    return True


def _pe_machine(path: str) -> int:
    """The machine field of a Windows executable's PE header, or 0."""
    try:
        with open(path, "rb") as f:
            head = f.read(4096)
        pe = int.from_bytes(head[0x3C:0x40], "little")
        return int.from_bytes(head[pe + 4:pe + 6], "little")
    except Exception:
        return 0


def _wrong_arch_engine() -> bool:
    """The app's own Ollama is the x64 build on an ARM64 PC (6b317)."""
    if not IS_WIN_ARM:
        return False
    exe = os.path.join(_MANAGED_BIN_DIR, "ollama.exe")
    return os.path.exists(exe) and _pe_machine(exe) == 0x8664


# THE NATIVE ENGINE ARRIVES BESIDE THE OLD ONE (6b317, from review). The
# first version moved the x64 engine aside and then downloaded: quitting
# during the download left no engine at all, chats failed meanwhile, and
# the x64 copy was stranded. Now the ARM64 build downloads into its own
# folder while the x64 one keeps serving, is checked to be ARM64, and
# goes in at a later launch, before any Ollama of ours starts.
_ENGINE_ARM_STAGE = _MANAGED_BIN_DIR + ".arm64"
_ENGINE_ARM_DONE = os.path.join(_ENGINE_ARM_STAGE, "complete")


def _stage_native_engine():
    if _other_millenai_running():
        return                    # one copy stages; the next launch checks
    try:
        shutil.rmtree(_ENGINE_ARM_STAGE, ignore_errors=True)
        _download_ollama_binary(_ENGINE_ARM_STAGE, row=None)
        if _pe_machine(os.path.join(_ENGINE_ARM_STAGE,
                                    "ollama.exe")) != 0xAA64:
            raise RuntimeError("the download is not an ARM64 engine")
        open(_ENGINE_ARM_DONE, "w").close()
    except Exception:
        shutil.rmtree(_ENGINE_ARM_STAGE, ignore_errors=True)


def _settle_engine_dir():
    """Before our Ollama starts: undo a swap cut short, then put a fully
    downloaded native engine in place. Any step that fails leaves the
    engine that was working; the swap is tried again next launch."""
    exe = "ollama.exe"
    old = _MANAGED_BIN_DIR + ".x64"
    if (not os.path.exists(os.path.join(_MANAGED_BIN_DIR, exe))
            and os.path.exists(os.path.join(old, exe))):
        shutil.rmtree(_MANAGED_BIN_DIR, ignore_errors=True)
        try:
            os.replace(old, _MANAGED_BIN_DIR)
        except OSError:
            return
    if not os.path.exists(_ENGINE_ARM_DONE) or _other_millenai_running():
        return
    if _pe_machine(os.path.join(_ENGINE_ARM_STAGE, exe)) != 0xAA64:
        shutil.rmtree(_ENGINE_ARM_STAGE, ignore_errors=True)
        return
    shutil.rmtree(old, ignore_errors=True)
    try:
        # fails while anything still runs from the old folder
        if os.path.exists(_MANAGED_BIN_DIR):
            os.replace(_MANAGED_BIN_DIR, old)
    except OSError:
        return
    try:
        os.replace(_ENGINE_ARM_STAGE, _MANAGED_BIN_DIR)
    except OSError:
        try:
            os.replace(old, _MANAGED_BIN_DIR)
        except OSError:
            pass
        return
    try:
        os.remove(os.path.join(_MANAGED_BIN_DIR, "complete"))
    except OSError:
        pass
    shutil.rmtree(old, ignore_errors=True)


def start_managed_engines():
    # MLX engines are started on demand (see ensure_mlx_engine) — each one
    # pins its whole model in RAM, so loading all of them at launch would
    # cost ~14 GB and starve the big Ollama models.
    if IS_WIN_ARM:
        _settle_engine_dir()
        if _wrong_arch_engine() and not os.path.exists(_ENGINE_ARM_DONE):
            # an ARM64 PC got the x64 engine before 6b317: fetch the
            # native one while the x64 one serves
            ctx_thread(target=_stage_native_engine,
                             daemon=True).start()
    _spawn_ollama_serve()
    # the app's own Ollama, if too old for a catalog model, fetches its
    # successor in the background for the next start (6b315); machine
    # work, on no profile
    ctx_thread(target=_stage_engine_update, bind=False, daemon=True).start()


# ------------------------------------------------------- first-run setup
_setup_lock = threading.Lock()
_setup_jobs = {}  # label -> {"status": "downloading"|"done"|"error", "note": str}


# TWO AT A TIME (6b290): a preset used to start every MLX download in
# its own thread at once — eleven streams sharing one pipe, each too slow
# to show a pulse. The rest wait as "queued", the way Ollama pulls do.
_MLX_GATE = threading.Semaphore(2)


def _download_model(label: str):
    repo = MLX_REPOS[label]
    try:
        from huggingface_hub import snapshot_download  # ships with mlx-lm
        with _MLX_GATE:
            with _setup_lock:
                _setup_jobs[label] = {"status": "downloading", "note": ""}
            snapshot_download(repo)
        # sweep carcasses: a KILLED earlier attempt leaves *.incomplete
        # blobs that poison the completeness check forever — a finished
        # 35B sat uncrowned behind eight of them (seen live)
        for p in glob.glob(os.path.join(
                _hf_model_dir(repo), "blobs", "*.incomplete")):
            try:
                os.remove(p)
            except Exception:
                pass
        with _setup_lock:
            _setup_jobs[label] = {"status": "done", "note": ""}
        _app_models_add(label)
        # not beside a benchmark's model (review of 6b331): the next
        # question starts it instead
        if not _bench["running"]:
            _spawn_mlx_engine(label)
            # the card says "Loading <model>…" until it answers (6b335)
            _proc = _mlx_procs.get(label)
            if _proc is not None and _proc.poll() is None:
                with _setup_lock:
                    if (_setup_jobs.get(label) or {}).get("status") == "done":
                        _setup_jobs[label]["loading_since"] = time.time()
    except Exception as exc:
        with _setup_lock:
            _setup_jobs[label] = {"status": "error", "note": str(exc)[:200]}


TITLE_PROMPT = (
    "Summarise what this message is about in 3 to 6 words, written like a "
    "headline: a noun phrase, not a question, not first person, no quotes "
    "and no final punctuation. Do not answer the message \u2014 only label "
    "its topic.\n\nMESSAGE: ")


def _clean_title(raw: str) -> str:
    title = " ".join(strip_think(strip_special(raw or "")).split())
    title = title.split("\n")[0]
    title = re.sub(r"^(topic|title)\s*:?\s*", "", title, flags=re.I)
    title = title.strip("\"'*#\u2014- .")
    return title if 2 < len(title) < 70 and not _looks_degenerate(title) \
        else ""


def make_title(text: str, conf=None, server=None, local: bool = True, ask_server: bool = True) -> str:
    """Name a chat with a small model — reusing whatever engine is already
    loaded, so it costs almost nothing. A chat the cloud answered is
    named by that provider's quick model instead (6b308): a keys-only
    user finally gets titles, and nothing new leaves the Mac. A chat
    "<server> Only" answered (6b337) is named by that server's model:
    `server` is its label, or "" for no title; never a local engine."""
    if server is not None:
        if not server:
            return ""
        try:
            parts = []
            server_stream(server, [{"role": "user",
                                    "content": TITLE_PROMPT + text[:600]}],
                          parts.append)
            return _clean_title("".join(parts))
        except Exception:
            return ""
    # `conf` is a ticket (6b326): the key is re-read now, and a provider
    # removed or re-keyed since the answer gets no call
    conf = _ticket_conf(conf) if conf else None
    if conf:
        m = cloud_role_model(_provider_of(conf), conf, "utility")
        if m:
            t = _clean_title(cloud_text(
                dict(conf, model=m, role="utility"),
                [{"role": "user", "content": TITLE_PROMPT + text[:600]}],
                timeout=15, max_tokens=300, quiet=True))
            if t:
                return t
    # the person's server before this computer (6b357); one that answered
    # with no usable title is not asked again on this computer
    # (never in a Cloud Only chat: nothing of it goes to a server, ask_server False)
    t = (server_side_text([{"role": "user", "content": TITLE_PROMPT + text[:600]}])
         if ask_server else None)
    if t is not None:
        return _clean_title(t)
    if not local:
        return ""
    pulled = ollama_pulled_tags() or set()
    usable = [l for l in MODEL_ROUTES
              if model_cached(l, pulled) and model_fits_memory(l)
              and not slow_giant(l)]
    # 1B models write poor titles; prefer something already resident, then
    # the smallest model that is still capable enough
    # 1B-class models produce garbage titles (seen looping "address address
    # address..."), so require a capable model even if a tiny one is resident
    capable = sorted((l for l in usable
                      if MODEL_MEM_BYTES.get(l, 0) >= 2.4e9),
                     key=lambda l: MODEL_MEM_BYTES.get(l, 0))
    live = [l for l in capable
            if MODEL_ROUTES[l][0] == "mlx" and _engine_up(MODEL_ROUTES[l][1])]
    order = (live[:1] + [l for l in capable if l not in live[:1]])[:2] \
        or usable[:1]
    for label in order:
        try:
            parts = []
            run_model(label, [{"role": "user",
                               "content": TITLE_PROMPT + text[:600]}],
                      parts.append)
            title = " ".join(
                strip_think(strip_special("".join(parts))).split())
            title = title.split("\n")[0]
            title = re.sub(r"^(topic|title)\s*:?\s*", "", title, flags=re.I)
            title = title.strip("\"'*#\u2014- .")
            if 2 < len(title) < 70 and not _looks_degenerate(title):
                return title
        except Exception:
            pass
    return ""


